public static class KeyboardLightingGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static int checks,layouts;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static Dictionary<string,object> Map(params object[] items){var map=new Dictionary<string,object>();for(int i=0;i<items.Length;i+=2)map.Add((string)items[i],items[i+1]);return map;}
 static Dictionary<string,object> Fixture(int mode=0,int brightness=50,int[] color=null,int pid=7588){return Map("deviceId","hid-0123456789abcdef","kind","keyboard","pid",pid,"connected",true,"online",true,"readbackConfirmed",true,"readCapabilities",new[]{"lighting","lightingSoftwareMode","windowsLightingEnabled"},"setCapabilities",new[]{"staticLighting"},"snapshot",Map("modelPid",pid,"profileCount",5,"activeProfile",0,"profileInformationUnconfirmed",false,"lightingEffectCode",mode,"lightingSoftwareMode",false,"windowsLightingEnabled",false,"uniformStaticLightingProtocolAvailable",true,"uniformStaticLightingReady",true,"lighting",Map("currentMode",mode,"recipeMode",0,"area",0,"speed",4,"flags",0,"brightness",brightness,"color",color??new[]{255,96,0},"secondaryColor",new[]{0,0,0},"backgroundColor",new[]{0,0,0})));}
 static Dictionary<string,object> Clone(Dictionary<string,object> state){var json=new JavaScriptSerializer();return json.Deserialize<Dictionary<string,object>>(json.Serialize(state));}
 static Dictionary<string,object> Snapshot(Dictionary<string,object> state){return (Dictionary<string,object>)state["snapshot"];}
 static Dictionary<string,object> Recipe(Dictionary<string,object> state){return (Dictionary<string,object>)Snapshot(state)["lighting"];}
 static object Get(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static object Invoke(MainWindow window,string method,params object[] args){return typeof(MainWindow).GetMethod(method,Hidden).Invoke(window,args);}
 static IEnumerable<T> Logical<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var item=child as DependencyObject;if(item==null)continue;foreach(T match in Logical<T>(item))yield return match;}}
 static T Tagged<T>(DependencyObject root,string tag)where T:FrameworkElement{return Logical<T>(root).Single(item=>Object.Equals(item.Tag,tag));}
 static void Pump(FrameworkElement root){root.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(new Action(()=>{}),DispatcherPriority.Background);root.UpdateLayout();}

 static void Pure() {
  var good=KeyboardLightingUiFacts.Read(Fixture());Check(good.IdentityConfirmed&&good.RecipeConfirmed&&good.CanRequestStatic&&good.StaticCurrent,"verified static recipe is displayable");Check(good.Brightness==50&&good.Color.SequenceEqual(new[]{255,96,0}),"RGB and brightness are observed fields");
  foreach(int pid in new[]{7586,7588})foreach(int mode in Enumerable.Range(0,10)){var state=Fixture(mode,0,new[]{0,0,0},pid);var result=KeyboardLightingUiFacts.Read(Clone(state));Check(result.RecipeConfirmed&&result.CanRequestStatic,"prepared exact model preserves stored recipe at mode "+mode);Check(result.StaticCurrent==(mode==0),"stored static recipe is current only at static mode "+mode);Check(result.Brightness==0&&result.Color.All(value=>value==0),"zero brightness and black are valid values");}
  foreach(int pid in new[]{0,7489,7546,7548,7587,7589,65535}){var result=KeyboardLightingUiFacts.Read(Fixture(0,50,null,pid));Check(!result.IdentityConfirmed&&!result.CanRequestStatic&&!result.StaticCurrent,"related or unknown model gains no keyboard lighting capability");}
  foreach(string id in new[]{null,"","keyboard","hid-0123456789abcde","hid-0123456789abcdef-7548","hid-0123456789abcdef-7586","hid-0123456789abcdef ","HID-0123456789ABCDEF","hid-0123456789abcdeg"}){var state=Fixture();state["deviceId"]=id;Check(!KeyboardLightingUiFacts.Read(state).IdentityConfirmed,"invalid or mismatched identity rejected");}
  var routed=Fixture();routed["deviceId"]="hid-0123456789abcdef-7588";Check(KeyboardLightingUiFacts.Read(routed).IdentityConfirmed,"exact paired-device identity accepted");
  foreach(string flag in new[]{"connected","online","readbackConfirmed"})foreach(object invalid in new object[]{false,null,"true",1,0}){var state=Fixture();state[flag]=invalid;var result=KeyboardLightingUiFacts.Read(state);Check(!result.IdentityConfirmed&&!result.StaticCurrent&&!result.CanRequestStatic,"state flags are strictly boolean: "+flag);}
  foreach(object value in new object[]{null,"7588",7588.0,true,7489}){var state=Fixture();state["pid"]=value;Check(!KeyboardLightingUiFacts.Read(state).IdentityConfirmed,"PID must be exact typed identity");state=Fixture();Snapshot(state)["modelPid"]=value;Check(!KeyboardLightingUiFacts.Read(state).IdentityConfirmed,"snapshot identity must match");}
  foreach(string capability in new[]{"lighting","lightingSoftwareMode","windowsLightingEnabled"}){var state=Fixture();state["readCapabilities"]=((string[])state["readCapabilities"]).Where(v=>v!=capability).ToArray();var result=KeyboardLightingUiFacts.Read(state);Check(!result.StaticCurrent&&!result.CanRequestStatic,"missing field capability stays unknown: "+capability);}
  var readOnly=Fixture();readOnly["setCapabilities"]=new string[0];var readonlyResult=KeyboardLightingUiFacts.Read(readOnly);Check(readonlyResult.StaticCurrent&&!readonlyResult.CanRequestStatic,"read-only confirmed fields remain visible");
  foreach(string flag in new[]{"lightingSoftwareMode","windowsLightingEnabled"})foreach(object invalid in new object[]{true,null,"false",0}){var state=Fixture();Snapshot(state)[flag]=invalid;var result=KeyboardLightingUiFacts.Read(state);Check(!result.StaticCurrent&&!result.CanRequestStatic,"unconfirmed lighting owner has no active parameter claims: "+flag);}
  foreach(string flag in new[]{"uniformStaticLightingProtocolAvailable","uniformStaticLightingReady"})foreach(object invalid in new object[]{false,null,"true",1}){var state=Fixture();Snapshot(state)[flag]=invalid;var result=KeyboardLightingUiFacts.Read(state);Check(!result.CanRequestStatic,"derived readiness must be explicit: "+flag);}
  foreach(string field in new[]{"currentMode","recipeMode","area","speed","flags","brightness"})foreach(object invalid in new object[]{null,"0",0.0,true,-1,256}){var state=Fixture();Recipe(state)[field]=invalid;var result=KeyboardLightingUiFacts.Read(state);Check(!result.RecipeConfirmed&&!result.StaticCurrent&&!result.CanRequestStatic,"invalid recipe field rejected: "+field);}
  foreach(object color in new object[]{null,"#FF0000",new int[0],new[]{1,2},new[]{1,2,3,4},new[]{-1,2,3},new[]{1,2,256},new object[]{"1",2,3},new object[]{1.0,2,3},new object[]{true,2,3}})foreach(string field in new[]{"color","secondaryColor","backgroundColor"}){var state=Fixture();Recipe(state)[field]=color;Check(!KeyboardLightingUiFacts.Read(state).RecipeConfirmed,"invalid RGB shape rejected: "+field);}
  foreach(int flags in new[]{1,16,17}){var state=Fixture();Recipe(state)["flags"]=flags;var result=KeyboardLightingUiFacts.Read(state);Check(result.RecipeConfirmed&&result.CanRequestStatic&&!result.StaticCurrent,"random/per-key saved recipe does not become a uniform active color");}
  foreach(string color in new[]{"secondaryColor","backgroundColor"}){var state=Fixture();Recipe(state)[color]=new[]{0,1,0};var result=KeyboardLightingUiFacts.Read(state);Check(result.RecipeConfirmed&&!result.StaticCurrent,"nonuniform background does not claim fixed RGB");}
  var mismatch=Fixture();Snapshot(mismatch)["lightingEffectCode"]=2;Check(!KeyboardLightingUiFacts.Read(mismatch).RecipeConfirmed,"conflicting current modes rejected");mismatch=Fixture();Snapshot(mismatch)["profileCount"]=0;Check(!KeyboardLightingUiFacts.Read(mismatch).RecipeConfirmed,"unconfirmed firmware profile info rejected");
  var before=Fixture();var facts=KeyboardLightingUiFacts.Read(before);Check(KeyboardLightingUiFacts.SameRecipe(facts,KeyboardLightingUiFacts.Read(Clone(before))),"unchanged JSON round-trip observation matches");var sessions=new Dictionary<string,Dictionary<string,object>>{{"keyboard",before}};Check(KeyboardLightingUiFacts.SessionMatches(sessions,before,facts),"current keyboard session permits its observed recipe");sessions["keyboard"]=Clone(before);Check(!KeyboardLightingUiFacts.SessionMatches(sessions,before,facts),"same identity in a new session rejects old keyboard UI callback");sessions.Clear();Check(!KeyboardLightingUiFacts.SessionMatches(sessions,before,facts),"removed session rejects keyboard callback");Recipe(before)["brightness"]=75;Check(!KeyboardLightingUiFacts.SameRecipe(facts,KeyboardLightingUiFacts.Read(before)),"changed recipe rejects obsolete callback");before=Fixture();facts=KeyboardLightingUiFacts.Read(before);before["deviceId"]="hid-fedcba9876543210";Check(!KeyboardLightingUiFacts.SameRecipe(facts,KeyboardLightingUiFacts.Read(before)),"changed device rejects obsolete callback");Check(!KeyboardLightingUiFacts.SameRecipe(null,facts),"missing observation rejects callback");Check(!KeyboardLightingUiFacts.Read(null).IdentityConfirmed,"missing reply is unknown");
 }

 static Dictionary<string,object> HeadsetFixture(int effect=1,int brightness=50,bool enabled=true,bool aura=false){return Map("deviceId","hid-0123456789abcdef","kind","headset","pid",7489,"connected",true,"online",true,"readbackConfirmed",true,"readCapabilities",new[]{"lighting","lightingEnabled","auraEnabled"},"setCapabilities",new[]{"lightingEnabled","lightingEffect","brightness","lightingColor","auraEnabled"},"snapshot",Map("modelPid",7489,"lightingEffectCode",effect,"brightnessRaw",brightness,"color",new[]{255,96,0},"lightingEnabled",enabled,"auraEnabled",aura));}
 static void PureHeadset() {
  foreach(int effect in Enumerable.Range(1,5))foreach(int brightness in new[]{0,47,50,100}){var result=HeadsetLightingUiFacts.Read(Clone(HeadsetFixture(effect,brightness)));Check(result.IdentityConfirmed&&result.Effect==effect&&result.Brightness==brightness,"headset raw confirmed values survive without rounding");Check(result.CanTogglePower&&result.CanSetEffect&&result.CanSetBrightness&&result.CanSetAura,"current headset capabilities remain available");Check(result.CanSetColor==(effect<=3),"cycle/rainbow never expose RGB write even when a supplied capability claims it");}
  var off=HeadsetLightingUiFacts.Read(HeadsetFixture(1,50,false));Check(off.Enabled==false&&off.CanTogglePower&&!off.CanSetEffect&&!off.CanSetBrightness&&!off.CanSetColor&&!off.CanSetAura,"power-off restricts editing to the confirmed power switch");var aura=HeadsetLightingUiFacts.Read(HeadsetFixture(1,50,true,true));Check(aura.AuraEnabled==true&&aura.CanSetAura&&!aura.CanSetEffect&&!aura.CanSetColor&&!aura.CanSetBrightness,"Aura owns the lights until the user releases it");
  foreach(int effect in new[]{-1,0,6,255}){var result=HeadsetLightingUiFacts.Read(HeadsetFixture(effect));Check(!result.Effect.HasValue&&!result.CanSetEffect&&!result.CanSetBrightness&&!result.CanSetColor,"unknown headset effect gains no parameter setter");}
  foreach(int brightness in new[]{-1,101,255}){var result=HeadsetLightingUiFacts.Read(HeadsetFixture(1,brightness));Check(!result.Brightness.HasValue&&!result.CanSetEffect&&!result.CanSetBrightness&&!result.CanSetColor,"invalid brightness does not become zero");}
  foreach(string flag in new[]{"connected","online","readbackConfirmed"})foreach(object invalid in new object[]{false,null,"true",1}){var state=HeadsetFixture();state[flag]=invalid;var result=HeadsetLightingUiFacts.Read(state);Check(!result.IdentityConfirmed&&!result.Enabled.HasValue&&!result.Brightness.HasValue,"headset strict session boolean: "+flag);}
  foreach(string flag in new[]{"lightingEnabled","auraEnabled"})foreach(object invalid in new object[]{null,"true",1,0}){var state=HeadsetFixture();Snapshot(state)[flag]=invalid;var result=HeadsetLightingUiFacts.Read(state);Check(flag=="lightingEnabled"?!result.Enabled.HasValue:!result.AuraEnabled.HasValue,"unknown headset flag not coerced");Check(!result.CanSetEffect&&!result.CanSetBrightness&&!result.CanSetColor&&!result.CanSetAura,"unknown power/owner blocks dependent setters");}
  foreach(string capability in new[]{"lighting","lightingEnabled","auraEnabled"}){var state=HeadsetFixture();state["readCapabilities"]=((string[])state["readCapabilities"]).Where(v=>v!=capability).ToArray();var result=HeadsetLightingUiFacts.Read(state);Check(!result.CanSetEffect&&!result.CanSetBrightness&&!result.CanSetColor,"read capability protects headset parameters: "+capability);}
  foreach(int pid in new[]{7488,7490,7588,0}){var state=HeadsetFixture();state["pid"]=pid;Snapshot(state)["modelPid"]=pid;Check(!HeadsetLightingUiFacts.Read(state).IdentityConfirmed,"other headset model does not inherit 7489 protocol");}
  foreach(object mapping in new object[]{true,"false",0}){var state=HeadsetFixture();Snapshot(state)["lightingModeMappingUnconfirmed"]=mapping;Check(!HeadsetLightingUiFacts.Read(state).Effect.HasValue,"explicit unconfirmed/ill-typed effect mapping stays unknown");}
  var missingColor=HeadsetFixture();Snapshot(missingColor).Remove("color");var noColor=HeadsetLightingUiFacts.Read(missingColor);Check(noColor.Effect==1&&noColor.Color==null&&!noColor.CanSetEffect&&!noColor.CanSetBrightness&&!noColor.CanSetColor,"missing preserved RGB blocks packet builders without hiding the valid effect field");
  var before=HeadsetFixture();var facts=HeadsetLightingUiFacts.Read(before);Check(HeadsetLightingUiFacts.Same(facts,HeadsetLightingUiFacts.Read(Clone(before))),"unchanged headset session matches");var sessions=new Dictionary<string,Dictionary<string,object>>{{"headset",before}};Check(HeadsetLightingUiFacts.SessionMatches(sessions,before,facts),"current headset session permits observed fields");sessions["headset"]=Clone(before);Check(!HeadsetLightingUiFacts.SessionMatches(sessions,before,facts),"same identity in a new session rejects old headset UI callback");sessions.Clear();Check(!HeadsetLightingUiFacts.SessionMatches(sessions,before,facts),"removed headset session rejects callback");Snapshot(before)["auraEnabled"]=true;Check(!HeadsetLightingUiFacts.Same(facts,HeadsetLightingUiFacts.Read(before)),"new lighting owner invalidates obsolete headset callback");before=HeadsetFixture();facts=HeadsetLightingUiFacts.Read(before);before["deviceId"]="hid-fedcba9876543210";Check(!HeadsetLightingUiFacts.Same(facts,HeadsetLightingUiFacts.Read(before)),"new headset identity invalidates obsolete callback");Check(!HeadsetLightingUiFacts.Read(null).IdentityConfirmed,"absent headset is unknown");
 }

 static void Use(MainWindow window,Dictionary<string,object> state) {
  var states=(Dictionary<string,Dictionary<string,object>>)Get(window,"gearStates");states.Clear();if(state!=null)states["keyboard"]=state;((Dictionary<string,string>)Get(window,"gearTabs"))["keyboard"]="灯光";Invoke(window,"ShowPage","device:keyboard");((ScrollViewer)Get(window,"pageScroll")).ScrollToTop();
 }
 static void Layout(MainWindow window,Dictionary<string,object> state,int width,string scenario,string output) {
  Use(window,state);var root=(FrameworkElement)window.Content;int height=width==1180?726:826;root.Measure(new Size(width,height));root.Arrange(new Rect(0,0,width,height));Pump(root);
  var surface=Tagged<Canvas>(root,"KeyboardLighting.Surface");var viewport=Tagged<ScrollViewer>(root,"KeyboardLighting.Viewport");var frame=Tagged<Border>(surface,"KeyboardLighting.Parameters");var facts=KeyboardLightingUiFacts.Read(state);
  Check(surface.Width==1246&&surface.Height==605,"fixed original body proportions");double bodyY=surface.TransformToAncestor(root).Transform(new Point()).Y;Check(bodyY>=116&&bodyY<=144,"integrated fixed header/body origin: "+scenario+"/"+width+"/"+bodyY);Check(frame.Width==377&&frame.Height==479&&Canvas.GetLeft(frame)==831&&Canvas.GetTop(frame)==80,"right original parameter rectangle");
  Check(!Logical<Image>(surface).Any(),"no left photo or vendor bitmap assets");var effects=Logical<Button>(surface).Where(button=>Convert.ToString(button.Tag).StartsWith("KeyboardLighting.Effect.",StringComparison.Ordinal)).ToArray();Check(effects.Length==10,"ten screenshot-proven basic effects");for(int index=0;index<effects.Length;index++){Check(Canvas.GetLeft(effects[index])==29+(index%5)*132&&Canvas.GetTop(effects[index])==121+(index/5)*116,"five columns by two rows");Check(!effects[index].IsEnabled,"render-only effect disabled");}
  var total=Tagged<CheckBox>(surface,"KeyboardLighting.TotalPower");Check(total.IsChecked==null&&!total.IsEnabled,"software control ownership cannot masquerade as light power");var swatch=Tagged<Button>(surface,"KeyboardLighting.Color");var title=Tagged<TextBlock>(surface,"KeyboardLighting.CurrentTitle");Check(title.Text==(facts.StaticCurrent?"恒亮":"—"),"title only claims confirmed static mode");Check(!swatch.IsEnabled,"render-only color edit disabled");
  var slider=Logical<Slider>(surface).Single();Check(Object.Equals(slider.Tag,facts.StaticCurrent)&&!slider.IsEnabled,"slider truth follows current observed mode");slider.ApplyTemplate();var track=(Track)slider.Template.FindName("PART_Track",slider);Check(track.Visibility==(facts.StaticCurrent?Visibility.Visible:Visibility.Collapsed),"unknown brightness has no fake zero thumb or progress");if(facts.StaticCurrent){Check(slider.Value==facts.Brightness.Value,"actual brightness retained including zero");var chip=(Border)swatch.Content;var rgb=((SolidColorBrush)chip.Background).Color;Check(rgb.R==facts.Color[0]&&rgb.G==facts.Color[1]&&rgb.B==facts.Color[2],"actual swatch retained including black");}else Check(swatch.ToolTip.ToString()=="状态未知","stored dynamic recipe never displayed as active RGB");
  foreach(var block in Logical<TextBlock>(surface)){if(block.ActualWidth<=0||block.ActualHeight<=0)continue;Check(block.TextWrapping!=TextWrapping.NoWrap||block.DesiredSize.Width-block.Margin.Left-block.Margin.Right<=block.ActualWidth+1,"body text has no intrinsic clipping: "+block.Text);var bounds=block.TransformToAncestor(surface).TransformBounds(new Rect(0,0,block.ActualWidth,block.ActualHeight));Check(bounds.Left>=-1&&bounds.Right<=surface.Width+1,"text fits original canvas: "+block.Text);}
  Check(viewport.HorizontalScrollBarVisibility==ScrollBarVisibility.Auto,"narrow body stays reachable by local horizontal scrolling");Check(width==1180?viewport.ScrollableWidth>350:viewport.ScrollableWidth<1,"expected original-width viewport");
  if(output!=null)Save(root,width,height,output,scenario+"-"+width+".png");viewport.ScrollToRightEnd();var outer=(ScrollViewer)Get(window,"pageScroll");outer.ScrollToBottom();Pump(root);var boundsAfter=frame.TransformToAncestor(root).TransformBounds(new Rect(0,0,frame.ActualWidth,frame.ActualHeight));Check(boundsAfter.Right<=width-20+1&&boundsAfter.Left>=248,"entire parameter panel reachable at both widths");Check(boundsAfter.Bottom<=height-20,"parameter bottom reachable without native window");if(output!=null&&width==1180)Save(root,width,height,output,scenario+"-"+width+"-right.png");
  foreach(var button in Logical<Button>(surface))button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));slider.Value=99;slider.RaiseEvent(new DragCompletedEventArgs(0,0,false){RoutedEvent=Thumb.DragCompletedEvent});Pump(root);Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null,"unshown window has no native presentation source");Check(!((WorkerClient)Get(window,"gearWorker")).Running,"render-only events launch no worker");Check(!(bool)Get(window,"busy"),"render-only events do not begin device operations");layouts++;
 }
 static void Save(FrameworkElement root,int width,int height,string output,string name){var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(output,name)))encoder.Save(stream);}

