 [STAThread]public static int Main(string[] args){try{string output=args.Length==2&&args[0]=="--render"?Path.GetFullPath(args[1]):null;if(output!=null)Directory.CreateDirectory(output);Pure();PureHeadset();var window=new MainWindow(true);((HardwareControlPolicy)Get(window,"hardwareControlPolicy")).SetEnabled(true);
  var cases=new Dictionary<string,Dictionary<string,object>>{{"static",Fixture()},{"zero",Fixture(0,0,new[]{0,0,0})},{"maximum",Fixture(0,100,new[]{255,255,255})},{"dynamic",Fixture(2)},{"unknown",null}};
